  tracks: ReadonlyMap<string, TrackEntry>,
  motions: ReadonlyMap<string, MotionEntry>,
): ProjectDefinition {
  return {
    ...this.#project,
    motions: [...motions.values()].map((entry) => ({
      ...entry.definition,
